<?php $__env->startSection('title','Product draft'); ?>
<?php $__env->startSection('content'); ?>
<div class="content container-fluid" style="max-width:1100px"><h1><?php echo e($draft->store->name); ?> — draft #<?php echo e($draft->id); ?></h1>
<p><?php echo e($draft->store->module->module_name); ?> · <?php echo e($draft->status); ?> · <?php echo e(str_replace('_',' ',$draft->step)); ?> · Updated <?php echo e($draft->updated_at); ?></p>
<?php if(session('saved')): ?><div class="alert alert-success">Action completed.</div><?php endif; ?>
<?php if($draft->needs_attention): ?><div class="alert alert-warning">Needs assistance: <?php echo e($draft->stalled_turns); ?> turns without progress. Draft details are preserved.</div><?php endif; ?>
<a class="btn btn-outline-primary mb-3" href="<?php echo e(route('admin.whatsapp.inbox.show',$draft->conversation_id)); ?>">Open conversation / assign human</a>
<?php if(!empty($draft->data['media_id'])): ?><div><img src="<?php echo e(route('admin.whatsapp.product-drafts.image',$draft)); ?>" alt="Vendor product photo" style="max-width:240px;max-height:240px;object-fit:contain"></div><?php endif; ?>
<div class="row"><div class="col-md-6"><h2>Collected details</h2><dl><?php $__currentLoopData = $draft->data; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $field=>$value): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><dt><?php echo e(str_replace('_',' ',$field)); ?></dt><dd><?php echo e(is_array($value)?json_encode($value):($value??'Not provided')); ?> <small class="text-muted"><?php echo e($draft->sources[$field]??'Vendor'); ?></small></dd><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></dl><p>Final product: <?php echo e($draft->item_id??'Not created'); ?></p></div>
<div class="col-md-6"><h2>Image analysis</h2><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?php echo e(json_encode($draft->vision,JSON_PRETTY_PRINT)); ?></pre><h2>Validation feedback</h2><pre style="white-space:pre-wrap"><?php echo e(json_encode($draft->errors,JSON_PRETTY_PRINT)); ?></pre></div></div>
<h2>Recent messages</h2><?php $__currentLoopData = $messages; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $message): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><p><strong><?php echo e($message->direction); ?> · <?php echo e($message->created_at); ?></strong><br><?php echo e($message->raw_text ?: data_get($message->content,'text.body',data_get($message->content,'text','Media / interactive message'))); ?></p><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>
<?php if(in_array($draft->status,['active','saved'])): ?><form method="POST" action="<?php echo e(route('admin.whatsapp.product-drafts.action',$draft)); ?>"><?php echo csrf_field(); ?><label for="action">Recovery action</label><select id="action" name="action" class="form-control"><option value="resume">Resume deterministic flow</option><option value="without_ai">Continue without AI</option><option value="retry_vision">Retry image analysis</option><option value="resend">Re-send current prompt (open reply window required)</option><option value="cancel">Cancel stale draft</option></select><label class="mt-3"><input type="checkbox" name="confirmed" value="1" required> I confirm this action on this vendor's draft.</label><br><button class="btn btn-primary">Apply action</button></form><?php endif; ?>
</div>
<?php $__env->stopSection(); ?>

